// The form is a scrolling screen: the editors are not lazy.
Column(
    modifier = Modifier.verticalScroll(rememberScrollState()),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
) {
    // Name and Description one under the other: side by side they would cut the name on a phone.
    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
        MonarchTextField(value = name, onValueChange = { name = it }, modifier = Modifier.fillMaxWidth(), label = "Name", required = true)
        MonarchTextField(value = description, onValueChange = { description = it }, modifier = Modifier.fillMaxWidth(), label = "Description (optional)")
    }
    MonarchSectionCard(title = "When", description = "The rule is checked whenever any of these happen.") {
        MonarchCheckboxGroup(
            options = triggers,
            value = chosen,
            onValueChange = { chosen = it },
        )
    }
    MonarchSectionCard(title = "If", description = "Leave empty to apply every time the rule is checked.") {
        MonarchConditionEditor(
            value = conditions,
            onValueChange = { conditions = it },
            fields = fields,
            match = match,
            onMatchChange = { match = it },
            showErrors = submitted,
        )
    }
    MonarchSectionCard(title = "Then", description = "Actions run in this order.") {
        MonarchActionEditor(
            value = actions,
            onValueChange = { actions = it },
            actionTypes = types,
            showErrors = submitted,
        )
    }
    MonarchSectionCard(title = "Options") {
        MonarchCheckboxRow(
            checked = on,
            onCheckedChange = { on = it },
            label = "Rule is on",
            description = "Rules that are off are kept but never run.",
        )
        MonarchCheckboxRow(
            checked = stop,
            onCheckedChange = { stop = it },
            label = "Stop processing",
            description = "When this rule matches, later rules are skipped for the same event.",
        )
    }
    MonarchTextField(value = priority, onValueChange = { priority = it }, label = {{extra.label}}, required = true)
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
        MonarchButton(text = "Cancel", onClick = { submitted = false }, variant = MonarchButtonVariant.Secondary)
        MonarchButton(text = "Save rule", onClick = { submitted = true }, variant = MonarchButtonVariant.Primary)
    }
}

