val fields = listOf(
    MonarchConditionField(
        key = "priority",
        label = "Priority",
        type = MonarchConditionFieldType.Select,
        options = listOf(
            MonarchSelectOption("low", "Low"),
            MonarchSelectOption("normal", "Normal"),
            MonarchSelectOption("high", "High"),
        ),
    ),
    MonarchConditionField(key = "subject", label = "Subject", type = MonarchConditionFieldType.Text),
    MonarchConditionField(
        key = "hoursOpen",
        label = "Hours since created",
        type = MonarchConditionFieldType.Number,
        placeholder = "Hours",
    ),
    MonarchConditionField(key = "tags", label = "Tags", type = MonarchConditionFieldType.Tags),
)
val types = listOf(
    MonarchActionType(
        key = "set_priority",
        label = "Set priority",
        parameters = listOf(
            MonarchActionParameter(
                key = "priority",
                label = "Priority",
                kind = MonarchActionParameterKind.Select,
                options = listOf(
                    MonarchSelectOption("normal", "Normal"),
                    MonarchSelectOption("high", "High"),
                ),
                required = true,
            ),
        ),
    ),
    MonarchActionType(
        key = "add_tags",
        label = "Add tags",
        parameters = listOf(
            MonarchActionParameter(key = "tags", label = "Tags", kind = MonarchActionParameterKind.Tags, required = true),
        ),
    ),
    MonarchActionType(
        key = "notify",
        label = "Notify the team",
        parameters = listOf(
            MonarchActionParameter(key = "message", label = "Message", kind = MonarchActionParameterKind.TextArea, required = true),
        ),
    ),
)
val triggers = listOf(
    MonarchCheckboxGroupOption("created", "Request created"),
    MonarchCheckboxGroupOption("updated", "Request updated"),
    MonarchCheckboxGroupOption("replied", "Requester replied"),
    MonarchCheckboxGroupOption("hourly", "Every hour", description = "Checks open requests on a schedule."),
)
var name by rememberSaveable { mutableStateOf("Raise priority of old requests") }
var description by rememberSaveable { mutableStateOf("") }
var on by rememberSaveable { mutableStateOf(true) }
var stop by rememberSaveable { mutableStateOf(false) }
var priority by rememberSaveable { mutableStateOf("10") }
var chosen by remember { mutableStateOf(listOf("hourly")) }
var conditions by remember {
    mutableStateOf(
        listOf(
            MonarchCondition(
                id = "c1",
                field = "hoursOpen",
                operator = MonarchConditionOperator.Gt,
                value = MonarchConditionValue.Number(24.0),
            ),
        ),
    )
}
var match by remember { mutableStateOf(MonarchConditionMatch.All) }
var actions by remember {
    mutableStateOf(
        listOf(MonarchRuleAction("a1", "set_priority", mapOf("priority" to MonarchActionValue.Text("high")))),
    )
}
var submitted by rememberSaveable { mutableStateOf(false) }

